insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('746b1fe5-9312-4688-8acf-78d313a7752a', 'ja', '店に入り、周りの人にあいさつして回ります。そのあとで、彼女に声をかけます。何が助けになりましたか？', '["社会的証明ができていたので、彼女がより心を開いている", "何も。立ち位置は、受け入れやすさに影響しない", "それでも、低い立ち位置を乗り越えなければならない", "声のかけ方が、無理をしているように感じられる"]'::jsonb, '前向きなやり取りが立ち位置を上げ、彼女をより受け入れやすくします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c790b664-f094-409a-9440-448401e0ec8e', 'ja', '新しい環境で、どうすれば社会的な立ち位置をすばやく築けますか？', '["人と人を引き合わせる", "スタッフや主催者に、敬意を持って接する", "一人だけに集中する", "グループのエネルギーに、前向きに貢献する"]'::jsonb, 'その場の人のつながりに価値を足すことは、一人だけを追いかけるよりも速く、立ち位置を上げます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d799275-6cc6-4451-9db7-bfb0e563f9bc', 'ja', '会話の中で、男性を本当に面白くするものは何ですか？', '["エピソードと、ものの見方を生む人生を送っていること", "強い意見を持っていること", "求められればいつでも笑わせられること", "自分について、自信を持って話すこと"]'::jsonb, '面白い人生は、人を自然に引き込む、本物の経験を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8654d59-aeba-4ca6-b2c9-c6824582ae10', 'ja', '面白い人生を送っている人のサインは、どれですか？', '["本物の経験から来るエピソードが、自然に出てくる", "純粋な好奇心から、より良い質問をする", "今取り組んでいることや関心ごとについて、熱を込めて話す", "上のすべて"]'::jsonb, '面白い人生は、人を自然に引き込む、本物の経験を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dd4c710-136c-4930-a752-e6a21ba5f5ac', 'ja', '面白い人生は、会話のあり方をどう変えますか？', '["話すことを、演技に変える", "掘り起こさなくても、自然な話題をくれる", "本物の経験から、人を引きつけるエネルギーを生む"]'::jsonb, '面白い人生は、無理のない、引き込まれるやり取りを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a96beb76-cf2b-44bb-8339-887ee43c1e0e', 'ja', 'ミステリアスさは、なぜ惹かれる気持ちの助けになるのですか？', '["不確かさが、彼女の頭を引きつけ、好奇心を保つから", "脳は、全体像をつかみきれないものに、より多くの注意を向けるから", "情報を浴びせるのではなく、彼女がこちらを知っていく余地を残すから", "上のすべて"]'::jsonb, 'ミステリアスさは、好奇心と発見の余地を残すことで、注意を引きつけ続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87f62533-abcc-4fdd-ab12-24b45f5f4be0', 'ja', '彼女が、仕事は何をしているのかと尋ねます。最もミステリアスさを生む返しは、どれですか？', '["仕事と担当している案件を、細かく説明する", "「いろいろ少しずつ、ですね。主にクリエイティブ系です」と言って、彼女のことを尋ねる", "これまでの職歴を、すべて並べる", "「面白いことは何も」と言って、話題を変える"]'::jsonb, '興味を引くのに足りる分だけ話し、彼女の好奇心の余地を残しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f45fc9f5-e0a3-4d7b-87bc-840a0f414623', 'ja', '会話の序盤で自分のことを説明しすぎると、何が起こりますか？', '["彼女の想像力が、活発に働き続ける", "彼女が見つけたり、想像したりするものが、何も残らない", "全体像が見えてしまい、好奇心が薄れる"]'::jsonb, 'すべてを明かすと、不確かさがなくなり、頭の中での関わりが減ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59011032-6b21-4d79-aaf3-ebe1fcb14211', 'ja', '付き合う人たちは、女性に対する自信にどう影響しますか？', '["人との関わり方が、ふつうに感じられるか、変に感じられるかは、環境で決まる", "友人が、惹かれ合いのスキルを直接教えてくれる", "自信は、生物学的にうつる", "女性は、一人よりもグループを好む"]'::jsonb, '環境は、成長を後押しするか、ためらいを強めるかの、どちらかです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80bb97c5-90cf-434a-a890-08a1daa36c04', 'ja', '友人たちが、出かけることや新しい人に会うことを避けていると、何が起こりますか？', '["声をかけたいという気持ちが、時間とともに弱まる", "環境が、動かない方向へ押す", "声をかけることが、変わったことで、必要のないことに感じられてくる", "上のすべて"]'::jsonb, '避けることではなく、行動することを後押ししてくれる、自分から動く人たちのそばにいましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3863647b-81d5-4ab3-9b63-30861c071216', 'ja', '成長を大切にする仲間は、たいてい何をしてくれますか？', '["ためらっているとき、背中を押してくれる", "結果だけでなく、努力をたたえてくれる", "居心地よく、満足したままでいさせてくれる", "新しい人に出会う機会をつくってくれる"]'::jsonb, '自分から動く人たちのそばにいると、避けることではなく、自分から踏み出すことが後押しされます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b78be7b-c378-4416-a5d7-3266ab3c3dfc', 'ja', '人と関わる機会を、どうやって日課に組み込みますか？', '["疲れているときでも、誘いに「はい」と言う", "家にいるほうが楽なときでも、出かける", "気に入るかどうかわからなくても、グループに入ってみる", "上のすべて"]'::jsonb, '人と関わる機会は、「顔を出す」という小さな選択の繰り返しで育ちます。')
