insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbe59913-e0d6-4e3f-a500-abe814b9551c', 'ja', '人とのつながりは、時間とともにどう積み重なっていきますか？', '["一人が、多くの人につながることがある", "誘いが、新しい環境を生む", "どんなやり取りも、必ず何かに変わる"]'::jsonb, 'ひとつのつながりが、何十もの間接的なチャンスを開くことがあります。自分から外に出ていきましょう。')
