insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a683dd8f-530d-4c64-a862-57d8f10be86b', 'ja', '日課の中にある、身近な練習の機会は、どれですか？', '["行きつけのカフェの店員との、ちょっとした会話", "ジムでいつも見かける人との、短いやり取り", "スーパーのレジの列でのひと言", "上のすべて"]'::jsonb, '身近な小さなやり取りは、プレッシャーを減らし、継続する力を育てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb06d0a0-4845-4ac7-80b4-cca9c98be6a3', 'ja', '毎朝、同じカフェの店員に会います。練習として、何ができますか？', '["代わりに、夜の店に行くまで待つ", "居心地よくいるために、話すのを避ける", "ひと言かけるか、短く会話する"]'::jsonb, 'プレッシャーの少ない毎日のやり取りが、慣れとスキルを自然に育てます。')
