insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b9f59424-635d-4624-ad50-aa3dd25f6855', 'ja', '定期的な繰り返しは、何を生みますか？', '["行動を繰り返すことで、神経回路が強化される", "行動が、「たまにやること」から「自分はこういう人間だ」へ移る", "不安がぶり返すことと、避ける癖が根づくことを防ぐ", "上のすべて"]'::jsonb, '定期的な練習は、積み上げたものを守り、スキルが衰えるのを防ぎます。継続しましょう。')
