insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6b9ff5d-fc7a-4e92-91d3-57411235152b', 'ja', '練習を長く休んでいるあいだ、心理的に何が起こりますか？', '["スキルがさらに強まる", "避ける癖と不安が、根づく時間を得る", "神経回路が、効率的なままでいる", "進歩が、自動的に積み重なる"]'::jsonb, '休んでいるあいだに、心は、行動しない新しい理由をつくり出す余地を得ます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dd2cece1-3524-4319-bd95-d773079fa01b', 'ja', '無理なく続けられる継続を支える行動は、どれですか？', '["現実的な、週の最低ラインを決めること", "自信が持てるまで待つこと", "場数のあいだを、長く空けないこと", "小さなやり取りも、ちゃんとした一回として扱うこと"]'::jsonb, '激しさよりも、流れのほうが大切です。進歩は、一気にやることからではなく、続けることから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3529af51-9b76-41c8-868a-2a04a415dc15', 'ja', '「スキルを練習している」から「それをする人間である」へと自己認識が変わるとき、何が起こりますか？', '["その行動が、自己イメージと切り離せなくなる", "自分はうまくやれているという、外からの承認が必要なくなる", "その行為が、「していること」から「自分という人間」へ移る", "埋めるべきすき間がないので、勇気がもう必要なくなる"]'::jsonb, '行動が自分という人間と切り離せなくなり、「していること」が「自分という人間」になり、勇気を必要とするすき間がなくなる。それが、自己認識の変化です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('242a1957-a048-451a-9da7-8ab630640b24', 'ja', '自然にできる段階に達すると、なぜ声をかけるのに「勇気が必要なくなる」のですか？', '["何度もやってきたので、恐れが完全に消えるから", "自分という人間と、していることのあいだに、すき間がないから", "成功を重ねた自信が、ためらいをすべてなくすから", "腕が上がりすぎて、結果がもうどうでもよくなるから"]'::jsonb, '本来の自分に逆らって、無理に行動しているのではありません。ただ、自分という人間を表現しているのです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('371a7413-becb-4f2b-a50d-96a6e2786c70', 'ja', 'スキルを伸ばすうえでの「実験のマインドセット」を定義するものは、何ですか？', '["一回一回のやり取りを、本番の演技として扱うこと", "成功を、結果で測ること", "やり取りを、データ集めとして扱うこと", "断られるのを避けること"]'::jsonb, 'どのやり取りも役に立ちます。次に何を変えればいいかを教えてくれるからです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a3d26a9-590a-4af0-95f0-d6c8c35f7896', 'ja', 'ユーモアを試して、2回続けて空振りに終わります。実験のマインドセットに従うと、どうするべきですか？', '["自分にユーモアは向いていない", "声をかけるのをやめる", "もっと良い冗談を暗記する", "別のタイプのユーモアや、別の場面で試す"]'::jsonb, 'どのやり取りも、たとえうまくいかなくても、次に何を変えればいいかを教えてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e0261e-75cb-4bdc-917c-8d6e653f374a', 'ja', '実験のマインドセットは、断られる痛みをどうやって減らしますか？', '["すべての結果に、自尊心を結びつける", "やり取りを、データ集めとして扱う", "断られたことを、価値ある情報として見る"]'::jsonb, '結果は、自分の価値の証明ではなく、学びの機会になります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d642fd6-f52e-4ce4-95a1-e14b1034c645', 'ja', '自分らしくいることは、なぜつながりを良くするのですか？', '["惹かれる気持ちを保証するから", "不安を下げるから", "聞くことと、相手に合わせることに使える、頭の余裕が生まれるから", "断られるのを避けられるから"]'::jsonb, '演じるのをやめると、本当に関われるようになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8b12ca4-eea8-4651-a0ba-a39ced8e6aef', 'ja', 'もともと物静かで、よく観察するタイプです。一番合う駆け引きのスタイルは、どれですか？', '["矢継ぎ早の冗談と掛け合い", "長い説明", "間と、落ち着いたアイコンタクト", "絶えず褒めること"]'::jsonb, '緊張感の生み方は、自分の気質に合っているべきです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30871b25-0072-4ec6-a580-9ac5cb667148', 'ja', '自分らしいスタイルは、なぜ借りもののテクニックを上回るのですか？', '["本物のつながりに使える、頭のリソースが空くから", "もともとの人柄の強みと一致しているから", "演技を保つために、ふりをする必要があるから"]'::jsonb, '自分らしくいることは、労力を減らし、すでにうまくいっているものを活かします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3d6c847d-5687-4a4a-a269-96782bfa828d', 'ja', '声をかけても、礼儀正しい返事をもらって、すぐに終わることがよくあります。つまずきポイントは、どこですか？', '["関心をつかむ、うまい話しかけ方", "体の面で距離を縮めること", "長い会話を続けること", "うまく次につなげること"]'::jsonb, '結果が変わるのは、やり取りの中の一番弱い部分に練習を集中させたときです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53171673-bc87-47f9-a580-371caf722388', 'ja', '話しかけるのはうまくいき、会話も楽にできますが、友達どまりのままです。つまずきポイントは、どこですか？', '["話しかけること", "会話の流れ", "恋愛的な緊張感や遊び心を持ち込むこと", "次につなげること"]'::jsonb, '結果が変わるのは、やり取りの中の一番弱い部分に練習を集中させたときです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4195d2ca-e36c-4bd9-bb7e-e178e5d589ca', 'ja', '会話を始めるのはうまくいきますが、すぐに気まずくなります。つまずきポイントは、どこですか？', '["会話の流れを保ち、彼女を引き込み続けること", "最初のひと言を伝えること", "次につなげて、LINEを交換すること", "体の面で距離を縮めること"]'::jsonb, '結果が変わるのは、やり取りの中の一番弱い部分に練習を集中させたときです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b31c3930-629e-4aab-974a-035d198918d4', 'ja', '自分の弱点を、どうやって正確に見つけますか？', '["全体的な自信の問題だと決めつける", "複数のやり取りで、繰り返し失敗する箇所を観察する", "いつも決まって崩れる場所のパターンを振り返る"]'::jsonb, 'つまずきポイントは、具体的な、繰り返し崩れる瞬間から見えてきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e977c9fd-3fd5-421d-b9c4-259a05b8af45', 'ja', '成長の停滞期を抜け出すのに役立つ方法は、どれですか？', '["意図的に難易度を上げること", "環境を変えること", "やる気を取り戻すために、長く休むこと", "具体的な小さなスキルひとつに集中すること"]'::jsonb, '新しい挑戦は、適応と進歩を促します。長い休みは、避ける癖を強めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('07805ac1-99db-4876-9227-20fb20fbcd1f', 'ja', 'ミステリアスに見せる助けになるのは、どれですか？', '["細かいところを説明しすぎずに、エピソードを話す", "会話を通じて、少しずつ自分を明かす", "経歴をすべて並べずに、奥行きをにじませる", "上のすべて"]'::jsonb, 'ミステリアスさは、好奇心と発見の余地を残すことで、注意を引きつけ続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('09518935-f277-43f0-8803-f6f2caa97eee', 'ja', '「実験のマインドセット」とは、何ですか？', '["何が一番うまくいくかを見つけるために、いろいろなやり方を試すこと", "どんな結果も、データ集めとして扱うこと", "「成功したか、失敗したか」から、「何を学んだか」へ切り替えること", "上のすべて"]'::jsonb, '学びをひとつ引き出せたなら、そのやり取りは成功です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b4d034c-f347-48a4-bf5e-2826500c82c6', 'ja', '新しい最初のひと言を試したところ、とても良い会話につながります。次にどうするべきですか？', '["いつでもうまくいくと決めつけて、二度と変えない", "何がうまくいったかを書き留め、少しずつ変えて試しながら磨く", "もう完璧になった証拠だと受け取る", "うまくいったので、実験をやめる"]'::jsonb, '成功もデータです。それを使って、学び続け、調整し続けましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('142d920d-753e-4fc3-9a34-043fbf2cb37d', 'ja', '人が集まる場で、惹かれる気持ちに影響する、立ち位置の低さのサインはどれですか？', '["壁際や部屋の端に、一人で立っている", "ぎこちなく、無理に会話に割り込む", "会話にあまり加わらない、または人と話さない", "上のすべて"]'::jsonb, '立ち位置の低さのサインは、関わっていないこと、ぎこちない入り方、参加していないことから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1c3b9eb2-3e17-4722-a2ee-0b94061906e1', 'ja', '声をかける前に、強い不安を感じます。何を優先するべきですか？', '["最初のひと言を完璧にするために、もっとテクニックを学ぶ", "何時間も、心の準備をする", "不安が弱まるまで待つ", "結果に関係なく、今日、小さなやり取りをひとつする"]'::jsonb, '場数を通じて経験を繰り返すことで、神経系は「安全だ」ということに慣れていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e482ecd-547c-44e9-96d0-74c25f5ef813', 'ja', '女性は話すのを楽しんでくれますが、駆け引きを返してくることはありません。つまずきポイントは、どこですか？', '["感じがよく、親しみやすいこと", "恋愛的な緊張感や遊び心を持ち込むこと", "最初に声をかけて、受け入れてもらうこと", "LINEを交換したあとの連絡"]'::jsonb, '結果が変わるのは、やり取りの中の一番弱い部分に練習を集中させたときです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e3345b-49dd-42c7-86fd-931c5c032deb', 'ja', 'もともと落ち着いていて、思慮深いタイプです。一番合う駆け引きのスタイルは、どれですか？', '["間、まっすぐなアイコンタクト、そして意外な質問", "大きな声で、エネルギーの高い、大胆な言い切り", "面白い講師の冗談をまねること", "無理にストレートな褒め言葉を言うこと"]'::jsonb, '自分らしいつながりのために、原則は、もともとの人柄を通じて表現しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('324d0f15-f4f3-4d1e-aa8a-9a3dbbda9f55', 'ja', 'グループでの活動に参加すると、つながるチャンスはどう変わりますか？', '["すぐにつながりができることが保証される", "定期的に人と関わる機会と、新しい人への橋渡しが生まれる", "自分の世界が、小さく、先の読めるままになる"]'::jsonb, 'グループは、場数と間接的なつながりをもたらし、自然なチャンスを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('360f9f51-86bf-4779-ab39-a8155afc9bdd', 'ja', '選んで話すことは、なぜすべてを明かすことよりも強く惹かれる気持ちを生むのですか？', '["処理しきれないほどの情報を、彼女に浴びせるから", "好奇心が働く、不確かな部分を残すから", "すき間を埋めるように、彼女の想像力を招くから"]'::jsonb, 'ミステリアスさは「どんな人だろう」という思いをかき立て、知っていく過程を、少しずつの、引き込まれるものにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4826161e-e13f-4b37-8fe4-6ee85878fd7e', 'ja', 'チャンスを増やすために必要な考え方の切り替えは、どれですか？', '["人と関わる機会を、意識して日課に組み込む", "自信がなくても、新しい活動に「はい」と言う", "どんな努力にも、すぐに結果が出ることを期待する"]'::jsonb, '継続した行動が世界を広げ、チャンスが生まれるようになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48fe4298-aeef-4a2e-85e5-f1d2e2592692', 'ja', '実験のマインドセットは、何を可能にしますか？', '["自分を落伍者だと感じることなく、失敗できる", "経験を裁くのではなく、そこから学べる", "場面ごとに何がうまくいくかの、データベースを築ける", "上のすべて"]'::jsonb, '声をかけることを実験として扱えば、断られることは、失敗ではなくデータになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51e669d2-f554-48ce-843b-4c367370982e', 'ja', '場数は、なぜ声をかけるときの不安を減らすのですか？', '["より良いセリフが身につくから", "慣れを通じて、神経系を訓練するから", "時間とともに、感じる脅威を下げるから", "理屈によって、恐れを自信に置き換えるから"]'::jsonb, '不安は、考えることや準備することではなく、安全な経験を繰り返すことで薄れていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5eb79a5b-9ac8-45c2-9e9d-423d1d2916e4', 'ja', '最初のひと言に、礼儀正しいけれど平板な反応が返ってきます。次にどう考えるべきですか？', '["「今のひと言は届かなかった。次は何を変えられるだろう」", "「失敗した。自分はこういうのが下手だ」", "「どうせ、彼女には関心がなかったんだ」", "「今日は、もう声をかけるのをやめよう」"]'::jsonb, '変えられる要素を分析して、次に試すための役立つ情報を集めましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5feee0d2-d777-41cf-a17b-4a10cdba7c30', 'ja', '面白い人生を送っていることは、なぜ惹かれる気持ちの助けになるのですか？', '["自分自身の引力が生まれ、人が自然と引き寄せられるから", "自然に流れ出てくる、会話の材料になるから", "上の両方"]'::jsonb, '面白い人生は、人を自然に引き込む、本物の経験を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('609555df-ed41-4234-bb64-85b739483e7a', 'ja', '新しい人と定期的に関わる機会をつくる活動は、どれですか？', '["決まったスケジュールで行われる、グループのフィットネスクラス", "家ではなく、カフェで仕事をすること", "ランニングや料理など、定期的に集まる趣味のサークル", "上のすべて"]'::jsonb, '意識して人と関わる機会をつくり、場数を重ねることで、可能性が生まれてきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63f71c1b-3eab-460c-91fa-a52c22044efb', 'ja', '男性に仕事以外の人生があることを示すサインは、どれですか？', '["今学んでいることや、取り組んでいることに触れる", "世の中のことを、好奇心を持って話す", "自分について話すのを避ける", "充実した人生から生まれたエピソードを持っている"]'::jsonb, '実際に生きてきた経験は、その人の話し方に自然と表れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cbe70b0-30ea-4012-9096-6f2a5efad2ed', 'ja', '社会的な立ち位置は、なぜ最初に惹かれるうえで強い手がかりになるのですか？', '["富や名声を、直接示すから", "周りの好意的な反応が、「一緒にいて楽しい人だ」と伝えるから", "人は、誰が魅力的かについての、集団の一致した見方を信頼するから"]'::jsonb, '立ち位置は、その場が自分をどう評価しているかを映し、相手の受け入れやすさを左右します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79d8a1ab-f362-4b54-96da-46e704c946f6', 'ja', '店の中で、見られ方としての立ち位置を下げるサインは、どれですか？', '["部屋の端をうろうろしていること", "何人もの人から、温かくあいさつされること", "無理のある、唐突な声のかけ方", "その場で、見てわかるほどくつろいでいること"]'::jsonb, 'ぎこちない立ち位置と、無理のある関わり方は、その場にあまりなじんでいないことを示します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('835a240c-8530-4ebc-a1a2-6750a3953290', 'ja', '人に「聞いてもらえた」と感じさせるのが得意です。何を前面に出せますか？', '["エネルギーの高い掛け合い", "大きな声でエピソードを語ること", "ストレートで大胆な褒め言葉", "深い質問と、しっかり聞くこと"]'::jsonb, 'もともとの強みを使って、自分らしく打ち解けていきましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('929ddae6-c1d3-4185-b3f1-b34b2eb34346', 'ja', 'もともと熱量が高く、ストレートなタイプです。一番合う駆け引きのスタイルは、どれですか？', '["軽い掛け合いと、ふざけた冗談", "選び抜いた言葉と間を伴う、力強いアイコンタクト", "長いエピソードと、遠回しなほのめかし", "礼儀正しすぎる同意"]'::jsonb, '自分らしいつながりのために、原則は、もともとの人柄を通じて表現しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95566af1-be99-4506-bdd8-59bc1224aa22', 'ja', '継続することは、主に何から自分を守ってくれますか？', '["やる気の低下", "スキルの停滞", "不安がぶり返すことと、避ける癖が根づくこと", "人から断られること"]'::jsonb, '定期的な練習は、積み上げたものを守り、スキルが衰えるのを防ぎます。継続しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('971392d7-a116-4cf8-b454-2526464b795a', 'ja', '場数は、なぜ時間とともに、声をかけるときの不安を減らすのですか？', '["神経系が、なじみのあるものに適応するから", "慣れを通じて、「安全だ」と体に教えるから", "経験を繰り返すことで、脅威への反応が下がるから", "上のすべて"]'::jsonb, '継続した場数は、経験を通じて、恐れへの敏感さをやわらげます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('98fd5abd-0203-4c21-bbff-f869372f2335', 'ja', 'その場での、高い社会的な立ち位置を示すサインは、どれですか？', '["人のほうから探しに来て、会話に入れてくれる", "周りが、温かさと楽しさを持って話しかけてくる", "ぎこちなさではなく、くつろいだ様子でその場を動いている", "上のすべて"]'::jsonb, '高い立ち位置は、余裕、受け入れられていること、そして周りの自然な反応に表れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99d720d0-bfa1-45ff-a43b-49f9f15f631e', 'ja', '継続すると、なぜ時間とともに声をかけるのが楽に感じられるようになるのですか？', '["神経回路が、より効率的になるから", "脳が、その行動を「ふつうのこと」として分類するから", "恐れが、理屈によって取り除かれるから"]'::jsonb, '繰り返しは、神経回路を強化し、自己認識を変えて、必要な労力を減らします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afbf1b2d-da55-4722-9e2b-7044a65e1227', 'ja', '週末に、プレッシャーの高い場でしか声をかけません。これにはどんなリスクがありますか？', '["激しさのおかげで、より早く慣れる", "不安が、すぐに減る", "しっかりしたスキルが、すばやく身につく", "機会が少ないせいで、進歩が遅くなる"]'::jsonb, '場数がまれだと、その刺激がなじみのないままになり、高い不安が長引きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b1dad7ff-1e71-4b22-b734-b1ca8f1c8973', 'ja', '付き合う人たちが成長を妨げていることを示すサインは、どれですか？', '["新しい人に会おうとする努力を、ばかにする", "人が集まる場を、いつも避ける", "行動よりも、居心地のよさをすすめる", "こちらが取る小さなリスクを、応援してくれる"]'::jsonb, '避けることを当たり前にする仲間は、自信を静かにしぼませます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b72f662b-1295-4658-bb7a-cf26f14aea82', 'ja', '立ち位置は、どうすれば築けますか？', '["その場にいる人たちと、自然に関わる", "くつろいだ様子で、その場を動く", "会話に加わり、価値を足す", "ミステリアスに見せるために、一人で離れている"]'::jsonb, '本物の関わりが、「この人といるのは楽しい」という証拠を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bfac329b-b9e4-4dbf-9045-786f91c69c40', 'ja', 'もともと温かく、共感力のあるタイプです。一番合う駆け引きのスタイルは、どれですか？', '["純粋な関心が伝わる、深く、好奇心のある質問", "攻撃的で大胆な言い切り", "大きなエネルギーと、矢継ぎ早のからかい", "個人的な話題を、いっさい避けること"]'::jsonb, '自分らしいつながりのために、原則は、もともとの人柄を通じて表現しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3ffa6e0-05e2-488d-a7f5-392b781d19f9', 'ja', 'そのほうが楽なので、家にいることを選びがちです。隠れた代償は何ですか？', '["つながるチャンスが減る", "生産性が下がる", "エネルギーを失う", "基準が下がる"]'::jsonb, '居心地のよさは、目先の楽さと引き換えに、長い目で見た孤立をもたらします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d089015f-4147-45d7-a8b2-91b48d80f944', 'ja', '具体的なテクニックを学んでも、なぜ声をかけるときの不安は解消しないのですか？', '["テクニックは効かないから", "不安は理屈に合わないものだから", "神経系が警戒モードにあると、知識は使えないから", "自信は学べないものだから"]'::jsonb, '不安は、考えることや準備することではなく、安全な経験を繰り返すことで薄れていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5674fd6-bd0f-4780-bb0b-5afca3a759d9', 'ja', 'つながるチャンスを増やすことの、一番の目的は何ですか？', '["出かけるたびに、必ずデートにつなげること", "新しい人と、継続して関わる機会をつくること", "チャンスが自然に生まれるように、場数を増やすこと"]'::jsonb, '意識して人と関わる機会をつくり、場数を重ねることで、可能性が生まれてきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8b68638-1540-4aa1-a96a-3d316ea102b3', 'ja', '付き合う人たちは、声をかけることやつながることに、どう役立ちますか？', '["友人が、行動への後押しをしてくれる", "環境が、勇気を出すことを楽にしてくれる", "友人が、新しい人に出会う機会をくれる", "上のすべて"]'::jsonb, '環境は、成長を後押しするか、ためらいを強めるかの、どちらかです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db1590aa-6103-4532-bff1-7bcf8930cfef', 'ja', '会話の中でミステリアスさを保つ行動は、どれですか？', '["説明しすぎずに、質問に答えること", "隠しごとがないように、早い段階ですべてを話すこと", "奥行きを、少しずつ明かすこと", "さらに質問できる余地を残すこと"]'::jsonb, 'ミステリアスさとは、ペース配分のことです。隠すことでも、はぐらかすことでもありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db1e61cd-85f6-4787-a686-1e10e72ffe10', 'ja', '会話を自然と楽に、引き込まれるものにしてくれる暮らしの要素は、どれですか？', '["続けている趣味やスキル", "新しい経験への好奇心", "わくわくを運んでくれる「運命の人」を待つこと", "今、実際に取り組んでいること"]'::jsonb, '面白い人生は、がんばらなくても、会話の材料を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dda0749c-c9ba-4e4a-affe-2eb786b6ec12', 'ja', '面白い人生は、なぜ表面的な愛嬌を超えて、人を惹きつけるのですか？', '["本物のエピソードと、会話の材料をくれるから", "恋愛とは別に、自分の世界を持っていることを示すから", "すごい実績だけに頼っているから"]'::jsonb, '面白い人生は、人を自然に引き込む、本物の経験を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2c71b43-3067-41f1-9745-de39c9164feb', 'ja', 'もともと面白いタイプです。一番合う駆け引きのスタイルは、どれですか？', '["ユーモアと、遊び心のあるからかいを取り入れる", "強いアイコンタクトと、間を使う", "大胆でストレートな言い切りをする", "完全にまじめなままでいる"]'::jsonb, 'ユーモアという強みを活かして、自分なりのやり方で緊張感を表現しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e310c934-f43c-49b6-b568-70a8a9baf70c', 'ja', '実験のマインドセットのもとで、それでも進歩として数えられる結果は、どれですか？', '["はっきり断られること", "どちらともつかない反応", "短い会話", "上のすべて"]'::jsonb, '学びをひとつ引き出せたなら、そのやり取りは成功です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3d69b71-e0dd-4f11-b25f-ecc126cd2696', 'ja', '声をかけても、ほとんど乗ってもらえないまま、すぐに終わります。そのあと、何に意識を向けるべきですか？', '["それが、自分は力不足だという証拠であること", "似たような場面を避けること", "タイミング、エネルギー、最初のひと言など、次に変えて試せる要素", "次こそ、すぐに成功しなければならないこと"]'::jsonb, '変えられる要素を分析して、次に試すための役立つ情報を集めましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f3ef742e-f78a-42cd-a813-76571d61bce5', 'ja', 'ミステリアスさは、なぜ惹かれる気持ちを高めるのですか？', '["手の届かない人に見せるから", "彼女の想像力に、働く材料を与えるから", "自信のなさを隠すから", "気持ちのつながりを妨げるから"]'::jsonb, '好奇心は、欠けた情報によってかき立てられます。ミステリアスさが、彼女の頭を引きつけ続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
